namespace docking.widgets.filechooser;







class DirectoryListModel : AbstractListModel<File> {

	private List<File> fileList = new();

	/* @Override */
	public File getElementAt(int index) {
		return fileList.get(index);
	}

	public File set(int index, File file) {
		File oldFile = fileList.set(index, file);
		fireContentsChanged(this, index, index);
		return oldFile;
	}

	bool contains(File file) {
		return fileList.contains(file);
	}

	void insert(File file) {
		fileList.add(file);
		int index = fileList.size() - 1;
		fireIntervalAdded(this, index, index);
	}

	void setFiles(List<File> newFileList) {
		int size = fileList.size();
		fileList.clear();
		fireIntervalRemoved(this, 0, size);
		if (newFileList.size() != 0) {
			fileList.addAll(newFileList);
			fireIntervalAdded(this, 0, fileList.size() - 1);
		}
	}

	File getFile(int index) {
		if (index >= 0 && index < fileList.size()) {
			return fileList.get(index);
		}
		return null;
	}

	void update() {
		fireContentsChanged(this, 0, getSize() - 1);
	}

	int indexOfFile(File file) {
		return fileList.indexOf(file);
	}

	public List<File> getAllFiles() {
		return new(fileList);
	}

	/* @Override */
	public int getSize() {
		return fileList.size();
	}
}
